//! Synthetic VPK/vtex fixtures. No Valve data is used here: every byte is generated by the test.

use std::path::{Path, PathBuf};

use mapcro_extract::{Error, GameDir, SteamInfo, Vpk, decode_vtex, extract, write_png};

const HERO: &str = "panorama/images/heroes/test_mm_psd.vtex_c";
const MID: &str = "panorama/images/minimap/base/minimap_midtown_mid_psd.vtex_c";
const MID_TUNNELS: &str = "panorama/images/minimap/base/minimap_midtown_mid_tunnels_psd.vtex_c";
const RAT_TUNNELS: &str = "panorama/images/minimap/base/minimap_midtown_rat_tunnels_psd.vtex_c";

struct FixtureEntry {
    path: String,
    data: Vec<u8>,
    crc_override: Option<u32>,
}

struct Fixture {
    _dir: tempfile::TempDir,
    game: PathBuf,
}

fn build_fixture(entries: &[FixtureEntry]) -> Fixture {
    let dir = tempfile::tempdir().expect("create temp dir");
    let game = dir.path().join("citadel");
    std::fs::create_dir_all(&game).expect("create game dir");
    std::fs::write(
        game.join("steam.inf"),
        b"ClientVersion=1234\nServerVersion=1234\nSourceRevision=5678\nVersionDate=Jan 02 2030\nVersionTime=03:04:05\n",
    )
    .expect("write steam.inf");

    let mut chunk = Vec::new();
    let mut tree = Vec::new();

    for entry in entries {
        let (extension, folder, name) = split_vpk_path(&entry.path);
        let offset = chunk.len() as u32;
        let crc = entry
            .crc_override
            .unwrap_or_else(|| crc32fast::hash(&entry.data));
        chunk.extend_from_slice(&entry.data);

        tree.extend_from_slice(extension.as_bytes());
        tree.push(0);
        tree.extend_from_slice(folder.as_bytes());
        tree.push(0);
        tree.extend_from_slice(name.as_bytes());
        tree.push(0);
        tree.extend_from_slice(&crc.to_le_bytes());
        tree.extend_from_slice(&0u16.to_le_bytes()); // preload
        tree.extend_from_slice(&0u16.to_le_bytes()); // archive 0
        tree.extend_from_slice(&offset.to_le_bytes());
        tree.extend_from_slice(&(entry.data.len() as u32).to_le_bytes());
        tree.extend_from_slice(&0xFFFFu16.to_le_bytes());
        tree.push(0); // end of names for this folder
        tree.push(0); // end of folders for this extension
    }
    tree.push(0); // end of extensions

    std::fs::write(game.join("pak01_000.vpk"), &chunk).expect("write chunk");
    std::fs::write(game.join("pak01_dir.vpk"), vpk_dir(&tree)).expect("write dir vpk");

    Fixture { _dir: dir, game }
}

fn vpk_dir(tree: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(&0x55AA_1234u32.to_le_bytes());
    out.extend_from_slice(&2u32.to_le_bytes());
    out.extend_from_slice(&(tree.len() as u32).to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // file data section
    out.extend_from_slice(&0u32.to_le_bytes()); // archive md5 section
    out.extend_from_slice(&0u32.to_le_bytes()); // other md5 section
    out.extend_from_slice(&0u32.to_le_bytes()); // signature section
    out.extend_from_slice(tree);
    out
}

fn split_vpk_path(path: &str) -> (String, String, String) {
    let (folder, file) = match path.rsplit_once('/') {
        Some((folder, file)) => (folder.to_owned(), file.to_owned()),
        None => (" ".to_owned(), path.to_owned()),
    };
    let (name, extension) = match file.rsplit_once('.') {
        Some((name, extension)) => (name.to_owned(), extension.to_owned()),
        None => (file, String::new()),
    };
    (extension, folder, name)
}

fn build_vtex(width: u16, height: u16, format: u8, pixels: &[u8]) -> Vec<u8> {
    build_vtex_with_extra(width, height, format, 1, pixels, None)
}

fn build_vtex_with_extra(
    width: u16,
    height: u16,
    format: u8,
    mip_count: u8,
    pixels: &[u8],
    extra: Option<(u32, &[u8])>,
) -> Vec<u8> {
    let data_offset = 40usize;
    let extra_count = u32::from(extra.is_some());

    let mut data = Vec::new();
    data.extend_from_slice(&1u16.to_le_bytes()); // texture version
    data.extend_from_slice(&0u16.to_le_bytes()); // flags
    data.extend_from_slice(&[0u8; 16]); // reflectivity
    data.extend_from_slice(&width.to_le_bytes());
    data.extend_from_slice(&height.to_le_bytes());
    data.extend_from_slice(&1u16.to_le_bytes()); // depth
    data.push(format);
    data.push(mip_count);
    data.extend_from_slice(&0u32.to_le_bytes()); // picmip
    data.extend_from_slice(&8u32.to_le_bytes()); // extra data offset
    data.extend_from_slice(&extra_count.to_le_bytes());
    if let Some((kind, payload)) = extra {
        data.extend_from_slice(&kind.to_le_bytes());
        data.extend_from_slice(&8u32.to_le_bytes()); // payload follows this 12-byte entry
        data.extend_from_slice(&(payload.len() as u32).to_le_bytes());
        data.extend_from_slice(payload);
    }
    assert!(data.len() >= 40);

    let data_size = data.len();
    let file_size = data_offset + data_size;

    let mut out = Vec::new();
    out.extend_from_slice(&(file_size as u32).to_le_bytes());
    out.extend_from_slice(&12u16.to_le_bytes()); // resource header version
    out.extend_from_slice(&1u16.to_le_bytes()); // resource version
    out.extend_from_slice(&8u32.to_le_bytes()); // block table offset
    out.extend_from_slice(&1u32.to_le_bytes()); // block count
    out.extend_from_slice(b"DATA");
    out.extend_from_slice(&((data_offset as u32) - 20).to_le_bytes());
    out.extend_from_slice(&(data_size as u32).to_le_bytes());
    out.resize(data_offset, 0);
    out.extend_from_slice(&data);
    assert_eq!(out.len(), file_size);
    out.extend_from_slice(pixels);
    out
}

fn known_pixels() -> (Vec<u8>, Vec<u8>) {
    let mut bgra = Vec::new();
    let mut rgba = Vec::new();
    for index in 0..8u8 {
        let blue = index;
        let green = 10 + index;
        let red = 20 + index;
        let alpha = 200 + index;
        bgra.extend_from_slice(&[blue, green, red, alpha]);
        rgba.extend_from_slice(&[red, green, blue, alpha]);
    }
    (bgra, rgba)
}

fn read_png(path: &Path) -> (u32, u32, Vec<u8>) {
    let file = std::fs::File::open(path).expect("open png");
    let decoder = png::Decoder::new(std::io::BufReader::new(file));
    let mut reader = decoder.read_info().expect("read png info");
    let mut buffer = vec![0u8; reader.output_buffer_size().expect("png buffer size")];
    let info = reader.next_frame(&mut buffer).expect("read png frame");
    buffer.truncate(info.buffer_size());
    (info.width, info.height, buffer)
}

#[test]
fn vpk_round_trip_and_png() {
    let (bgra, rgba) = known_pixels();
    let fixture = build_fixture(&[FixtureEntry {
        path: HERO.to_owned(),
        data: build_vtex(4, 2, 28, &bgra),
        crc_override: None,
    }]);

    let game = GameDir::new(&fixture.game).expect("game dir");
    let vpk = Vpk::open(&game, "pak01_dir.vpk").expect("open vpk");
    let entry = vpk.entry(HERO).expect("entry");
    assert_eq!(entry.size(), 80 + bgra.len() as u64);

    let bytes = vpk.read(HERO).expect("read entry");
    let texture = decode_vtex(&bytes).expect("decode texture");
    assert_eq!((texture.width, texture.height), (4, 2));
    assert_eq!(texture.rgba, rgba);

    let out = tempfile::tempdir().expect("out dir");
    let path = out.path().join("test.png");
    write_png(&path, texture.width, texture.height, &texture.rgba).expect("write png");
    let (width, height, decoded) = read_png(&path);
    assert_eq!((width, height), (4, 2));
    assert_eq!(decoded, rgba);
}

#[test]
fn corrupted_crc_is_detected() {
    let (bgra, _) = known_pixels();
    let fixture = build_fixture(&[FixtureEntry {
        path: HERO.to_owned(),
        data: build_vtex(4, 2, 28, &bgra),
        crc_override: Some(0),
    }]);

    let game = GameDir::new(&fixture.game).expect("game dir");
    let vpk = Vpk::open(&game, "pak01_dir.vpk").expect("open vpk");
    match vpk.read(HERO) {
        Err(Error::CrcMismatch {
            expected, actual, ..
        }) => {
            assert_eq!(expected, 0);
            assert_ne!(actual, 0);
        }
        other => panic!("expected CrcMismatch, got {other:?}"),
    }
}

#[test]
fn path_traversal_is_refused() {
    let fixture = build_fixture(&[FixtureEntry {
        path: "../evil.vtex_c".to_owned(),
        data: vec![0u8; 16],
        crc_override: None,
    }]);

    let game = GameDir::new(&fixture.game).expect("game dir");
    let error = Vpk::open(&game, "pak01_dir.vpk").expect_err("traversal entry must fail");
    assert!(matches!(error, Error::UnsafePath(path) if path == "../evil.vtex_c"));
}

#[test]
fn non_allow_listed_path_is_refused() {
    let fixture = build_fixture(&[]);
    std::fs::write(fixture.game.join("cfg.txt"), b"not for the extractor").expect("write file");

    let game = GameDir::new(&fixture.game).expect("game dir");
    let error = game.path("cfg.txt").expect_err("path must be refused");
    assert!(matches!(error, Error::PathNotAllowed(path) if path == "cfg.txt"));

    assert!(GameDir::is_allowed("steam.inf"));
    assert!(GameDir::is_allowed("pak01_dir.vpk"));
    assert!(GameDir::is_allowed("pak01_000.vpk"));
    assert!(GameDir::is_allowed("maps/dl_midtown.vpk"));
    assert!(!GameDir::is_allowed("account_131034801.stats"));
    assert!(!GameDir::is_allowed("cache_131034801.soc"));
    assert!(!GameDir::is_allowed("cfg/config.cfg"));
    assert!(!GameDir::is_allowed("pak01_1000.vpk"));
}

#[test]
fn unsupported_format_is_typed() {
    let fixture = build_fixture(&[FixtureEntry {
        path: HERO.to_owned(),
        data: build_vtex(2, 2, 2, &[0u8; 16]), // DXT5
        crc_override: None,
    }]);

    let game = GameDir::new(&fixture.game).expect("game dir");
    let vpk = Vpk::open(&game, "pak01_dir.vpk").expect("open vpk");
    let bytes = vpk.read(HERO).expect("read entry");
    assert!(matches!(
        decode_vtex(&bytes),
        Err(Error::UnsupportedFormat(2))
    ));
}

#[test]
fn compressed_mips_are_refused() {
    let fixture = build_fixture(&[FixtureEntry {
        path: HERO.to_owned(),
        data: build_vtex_with_extra(2, 2, 28, 1, &[0u8; 16], Some((4, &[0u8; 4]))),
        crc_override: None,
    }]);

    let game = GameDir::new(&fixture.game).expect("game dir");
    let vpk = Vpk::open(&game, "pak01_dir.vpk").expect("open vpk");
    let bytes = vpk.read(HERO).expect("read entry");
    assert!(matches!(decode_vtex(&bytes), Err(Error::CompressedMips)));
}

#[test]
fn size_mismatch_is_typed() {
    let fixture = build_fixture(&[FixtureEntry {
        path: HERO.to_owned(),
        data: build_vtex(2, 2, 28, &[0u8; 15]),
        crc_override: None,
    }]);

    let game = GameDir::new(&fixture.game).expect("game dir");
    let vpk = Vpk::open(&game, "pak01_dir.vpk").expect("open vpk");
    let bytes = vpk.read(HERO).expect("read entry");
    assert!(matches!(
        decode_vtex(&bytes),
        Err(Error::TextureSizeMismatch {
            expected: 16,
            actual: 15
        })
    ));
}

#[test]
fn steam_inf_parses() {
    let info = SteamInfo::parse(
        "ClientVersion=6860\r\nSourceRevision=11211860\r\nVersionDate=Nov 05 2026\r\nVersionTime=16:40:40\r\n",
    )
    .expect("parse steam.inf");
    assert_eq!(info.client_version, 6860);
    assert_eq!(info.source_revision, 11211860);
    assert_eq!(info.version_date, "Nov 05 2026");
    assert_eq!(info.version_time, "16:40:40");
}

#[test]
fn output_inside_game_is_refused() {
    let fixture = build_fixture(&[]);
    let out = fixture.game.join("out");
    match extract(&fixture.game, &out) {
        Err(Error::OutputInsideGame(_)) => {}
        other => panic!("expected OutputInsideGame, got {other:?}"),
    }
    assert!(!out.exists());
}

#[test]
fn output_inside_repo_is_refused() {
    let fixture = build_fixture(&[]);
    let out = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("target")
        .join("extract-test-out");
    match extract(&fixture.game, &out) {
        Err(Error::OutputInsideRepo(_)) => {}
        other => panic!("expected OutputInsideRepo, got {other:?}"),
    }
    assert!(!out.exists());
}

#[test]
fn extract_writes_pack_and_blobs() {
    let (bgra, _) = known_pixels();
    let entries = [
        (MID, build_vtex(4, 2, 28, &bgra)),
        (MID_TUNNELS, build_vtex(4, 2, 28, &bgra)),
        (RAT_TUNNELS, build_vtex(4, 2, 28, &bgra)),
        (HERO, build_vtex(4, 2, 28, &bgra)),
    ]
    .into_iter()
    .map(|(path, data)| FixtureEntry {
        path: path.to_owned(),
        data,
        crc_override: None,
    })
    .collect::<Vec<_>>();
    let fixture = build_fixture(&entries);
    let out = tempfile::tempdir().expect("out dir");

    let report = extract(&fixture.game, out.path()).expect("extract");
    assert_eq!(report.files.len(), 4);
    assert_eq!(report.sources, 4);
    assert_eq!(report.blobs, 4);

    for file in [
        "map/minimap_midtown_mid.png",
        "map/minimap_midtown_mid_tunnels.png",
        "map/minimap_midtown_rat_tunnels.png",
        "heroes/test.png",
    ] {
        assert!(out.path().join(file).is_file(), "missing {file}");
    }

    let pack: serde_json::Value =
        serde_json::from_slice(&std::fs::read(out.path().join("pack.json")).expect("read pack"))
            .expect("parse pack");
    assert_eq!(pack["schema"].as_u64(), Some(1));
    assert_eq!(pack["extractor"]["name"].as_str(), Some("mapcro-extract"));
    assert_eq!(pack["game"]["client_version"].as_u64(), Some(1234));
    assert_eq!(pack["game"]["source_revision"].as_u64(), Some(5678));
    assert_eq!(pack["game"]["date"].as_str(), Some("Jan 02 2030"));
    assert_eq!(pack["sources"].as_array().expect("sources").len(), 4);
    assert_eq!(pack["blobs"].as_object().expect("blobs").len(), 4);
    assert_eq!(
        pack["blobs"]["heroes/test"]["file"].as_str(),
        Some("heroes/test.png")
    );
    assert_eq!(
        pack["blobs"]["heroes/test"]["sha256"]
            .as_str()
            .expect("sha256")
            .len(),
        64
    );
}

/// Local-only check against a real install. Run with:
/// `MAPCRO_GAME_DIR=~/.local/share/Steam/steamapps/common/Deadlock/game/citadel \
///  nix develop -c cargo test -p mapcro-extract --test extract -- --ignored real_install`
#[test]
#[ignore = "reads the local Deadlock install; set MAPCRO_GAME_DIR to run"]
fn real_install() {
    let Some(game) = std::env::var_os("MAPCRO_GAME_DIR") else {
        eprintln!("MAPCRO_GAME_DIR is not set; skipping real-install test");
        return;
    };

    let out = Path::new("/tmp/mapcro-extract-real");
    let _ = std::fs::remove_dir_all(out);
    let report = extract(Path::new(&game), out).expect("real extraction");

    assert!(out.join("map/minimap_midtown_mid.png").is_file());
    assert!(out.join("map/minimap_midtown_mid_tunnels.png").is_file());
    assert!(out.join("map/minimap_midtown_rat_tunnels.png").is_file());
    assert!(out.join("pack.json").is_file());
    assert!(
        report.files.iter().any(|file| file.starts_with("heroes/")),
        "no hero portraits were written"
    );

    eprintln!(
        "real install: {} PNGs, {} sources, {} blobs, pack at {}",
        report.files.len(),
        report.sources,
        report.blobs,
        report.pack.display()
    );
}
